        long[] sums = new long[256];
        long[] counts = new long[256];
        int[] hashes = new int[256];
        int size;
        int[] slots = new int[512];
        int mask = 511;

        static int hash(byte[] a, int off, int len) {
            int h = 0x811C9DC5;
            int end = off + len;
