            h ^= h >>> 15;
            h *= 0x2C1B3C6D;
            h ^= h >>> 12;
            return h;
        }

        static boolean same(byte[] k, byte[] a, int off, int len) {
            for (int i = 0; i < len; i++) if (k[i] != a[off + i]) return false;
